import { chromium } from 'playwright';

const URL = 'http://localhost:4173/';
const browser = await chromium.launch();
const context = await browser.newContext({ locale: 'en-US', viewport: { width: 900, height: 800 } });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

const check = (label, cond) => console.log(`${cond ? 'PASS' : 'FAIL'} - ${label}`);

await page.goto(URL);
await page.waitForSelector('h1');
const h1 = () => page.textContent('h1');
const htmlLang = () => page.evaluate(() => document.documentElement.lang);

check(`initial EN title (got "${await h1()}")`, (await h1()) === 'Profile settings');
check(`initial html lang en (got "${await htmlLang()}")`, (await htmlLang()) === 'en');

// Switch to Russian
await page.getByText('Русский', { exact: true }).click();
await page.waitForTimeout(200);
check(`RU title (got "${await h1()}")`, (await h1()) === 'Настройки профиля');
check(`RU html lang (got "${await htmlLang()}")`, (await htmlLang()) === 'ru');
check(`RU document.title (got "${await page.title()}")`, (await page.title()) === 'Настройки профиля');
check('RU name label', await page.getByText('Имя', { exact: true }).isVisible());
check('RU placeholder', (await page.getByPlaceholder('Введите имя').count()) === 1);
