// @vitest-environment jsdom
// TEMPORARY verification test — deleted after the run.
import { describe, it, expect, beforeAll } from 'vitest';
import { act, fireEvent, screen, waitFor } from '@testing-library/react';

describe('language switch (real main.tsx wiring)', () => {
  beforeAll(async () => {
    document.body.innerHTML = '<div id="root"></div>';
    window.localStorage.clear();
    Object.defineProperty(window.navigator, 'language', { value: 'en-US', configurable: true });
    await import('./main');
    await waitFor(() => expect(screen.getByRole('heading', { level: 1 })).toBeTruthy());
  });

  it('starts in English', () => {
    expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('Profile settings');
    expect(document.documentElement.lang).toBe('en');
    expect(screen.getByPlaceholderText('Enter your name')).toBeTruthy();
  });

  it('switches to Russian, including Gravity built-in strings', async () => {
    const radio = screen.getByRole('radio', { name: 'Русский' });
    await act(async () => {
      fireEvent.click(radio);
    });
    await waitFor(() =>
      expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('Настройки профиля'),
    );
    expect(document.documentElement.lang).toBe('ru');
    expect(document.title).toBe('Настройки профиля');
    expect(screen.getByPlaceholderText('Введите имя')).toBeTruthy();
    expect(screen.getByRole('button', { name: 'Сохранить' })).toBeTruthy();
    expect(screen.getByText('Подписаться на рассылку')).toBeTruthy();
    expect(screen.getByText('Встроенные компоненты Gravity UI также переведены.')).toBeTruthy();
    // Gravity Pagination's own strings
    expect(screen.getByPlaceholderText('Стр.')).toBeTruthy();
    expect(window.localStorage.getItem('app.language')).toBe('ru');
  });

  it('validates in Russian', async () => {
    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: 'Сохранить' }));
    });
    expect(screen.getByText('Пожалуйста, введите имя')).toBeTruthy();
    await act(async () => {
      fireEvent.change(screen.getByPlaceholderText('Введите имя'), { target: { value: 'Анна' } });
    });
    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: 'Сохранить' }));
    });
    expect(screen.getByText('Изменения сохранены')).toBeTruthy();
  });

  it('switches back to English and clears Russian text', async () => {
    await act(async () => {
      fireEvent.click(screen.getByRole('radio', { name: 'English' }));
    });
    await waitFor(() =>
      expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('Profile settings'),
    );
    expect(document.documentElement.lang).toBe('en');
    expect(screen.getByRole('button', { name: 'Save' })).toBeTruthy();
    expect(screen.getByPlaceholderText('Page #')).toBeTruthy();
    expect(document.body.textContent).not.toContain('Сохранить');
    expect(document.body.textContent).not.toContain('Настройки');
    expect(window.localStorage.getItem('app.language')).toBe('en');
  });
});

describe('language persistence and detection', () => {
  it('restores a saved Russian choice on load and does not reset it', async () => {
    window.localStorage.setItem('app.language', 'ru');
    document.body.innerHTML = '<div id="root"></div>';
    const { I18nProvider, useI18n } = await import('./i18n/I18nProvider');
    const { render } = await import('@testing-library/react');
    const Probe = () => {
      const { language } = useI18n();
      return <span data-testid="lang">{language}</span>;
    };
    const { getByTestId, unmount } = render(
      <I18nProvider>
        <Probe />
      </I18nProvider>,
    );
    expect(getByTestId('lang').textContent).toBe('ru');
    unmount();
  });

  it('ignores an invalid stored value and falls back to browser language', async () => {
    window.localStorage.setItem('app.language', 'de');
    Object.defineProperty(window.navigator, 'language', { value: 'ru-RU', configurable: true });
    const { I18nProvider, useI18n } = await import('./i18n/I18nProvider');
    const { render } = await import('@testing-library/react');
    const Probe = () => <span data-testid="lang">{useI18n().language}</span>;
    const { getByTestId, unmount } = render(
      <I18nProvider>
        <Probe />
      </I18nProvider>,
    );
    expect(getByTestId('lang').textContent).toBe('ru');
    unmount();
  });

  it('throws when useI18n is used outside the provider', async () => {
    const { useI18n } = await import('./i18n/I18nProvider');
    const { render } = await import('@testing-library/react');
    const Probe = () => <span>{useI18n().language}</span>;
    const spy = (await import('vitest')).vi.spyOn(console, 'error').mockImplementation(() => {});
    expect(() => render(<Probe />)).toThrow('useI18n must be used inside <I18nProvider>');
    spy.mockRestore();
  });
});

